    async def get_quota_shots_of_person_for_month(
        self,
        person_id: str,
        year: int,
        month: int,
        *,
        count_mode: Optional[Literal["weighted", "weighteddone", "feedback", "done"]] = None,
        project_id: Optional[str] = None,
        task_type_id: Optional[str] = None,
    ) -> list[dict[str, Any]]:
        """Get the quota shots of a person for a month.

        Get the shots that count in the quota of a person for a month. A quota shot is a
        shot that the person ended. An administrator reads the quotas of all persons.
        The person reads their own quotas. Give project_id to read the quotas of another
        person. You must then be a manager or a supervisor in the team of this project.
        The role held on the project team applies. A manager or a supervisor who gives a
        project_id of a project they are not a team member of gets a 403, also for their
        own quotas.

        Args:
            person_id: Person unique identifier
            year: Year, for example 2026
            month: Month, from 1 to 12
            count_mode: How to count the shots: weighted, weighteddone, feedback or
                done. The default value is weighted. The weighted modes give each shot the
                part of its work time that is in the period. The other modes count each shot
                on its end date. The feedback modes end a shot at its first feedback. The
                done modes end a shot when it is done.
            project_id: Get only the shots of this project
            task_type_id: Get only the shots of this task type

        ``GET /data/persons/{person_id}/quota-shots/month/{year}/{month}``
        """
        return await self._t.request(
            "GET",
            "/data/persons/{person_id}/quota-shots/month/{year}/{month}",
            path_params={"person_id": person_id, "year": year, "month": month},
            params={"count_mode": count_mode, "project_id": project_id, "task_type_id": task_type_id},
            response_type=list[dict[str, Any]],
        )

