    async def get_time_spent_table_by_year(
        self,
        *,
        project_id: Optional[str] = None,
        department_id: Optional[str] = None,
        studio_id: Optional[str] = None,
    ) -> dict[str, Any]:
        """Get the time spent table by year.

        Get a table of the time spent of each person for each year. Add project_id,
        department_id or studio_id to filter the table. An administrator gets the time
        spent of all persons. A manager gets the time spent logged on the tasks of the
        projects they manage, for all persons. A supervisor gets the time spent of the
        projects they supervise, for the task types of their departments. A supervisor
        without department gets all the task types. A manager or a supervisor who gives
        a project_id of another project gets a 403. A supervisor who gives a
        department_id that is not one of their departments gets a 400. Other users get
        their own time spent only. The filters still apply to them. The manager and
        supervisor roles are the roles held on the project team.

        Args:
            project_id: Get only the time spents of this project
            department_id: Get only the persons of this department
            studio_id: Get only the persons of this studio

        ``GET /data/persons/time-spents/year-table``
        """
        return await self._t.request(
            "GET",
            "/data/persons/time-spents/year-table",
            params={"project_id": project_id, "department_id": department_id, "studio_id": studio_id},
            response_type=dict[str, Any],
        )

