    async def invite_person(self, person_id: str) -> InvitePersonResponse:
        """Invite a person.

        Send an email that invites a person to log in to Kitsu. The email has a link to
        set the password. The link is valid for 7 days. You must be an administrator.

        Args:
            person_id: Person unique identifier

        ``GET /actions/persons/{person_id}/invite``
        """
        return await self._t.request(
            "GET",
            "/actions/persons/{person_id}/invite",
            path_params={"person_id": person_id},
            response_type=InvitePersonResponse,
        )

    async def get_password_reset_link(
        self,
        person_id: str,
    ) -> GetPasswordResetLinkResponse:
        """Get a password reset link.

        Get the password reset link of a person. This link is the same as the link in
        the password reset email. Thus, an administrator can send it by another way, for
        example when the email server is not set. If a reset token is valid, the route
        uses it again. Thus, a link that you sent before stays valid. Else, the route
        makes a new token. You must be an administrator.

        Args:
            person_id: Person unique identifier

        ``POST /actions/persons/{person_id}/reset-password-link``
        """
        return await self._t.request(
            "POST",
            "/actions/persons/{person_id}/reset-password-link",
            path_params={"person_id": person_id},
            response_type=GetPasswordResetLinkResponse,
        )

