    async def change_password_of_person(
        self,
        person_id: str,
        *,
        password: str,
        password_2: str,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> ChangePasswordOfPersonResponse:
        """Change the password of a person.

        Set a new password for a person. Give the new password two times. You cannot
        change the password of a protected account. You cannot change the password of
        another administrator who already has a password. You can set the first password
        of a new administrator. The person gets an email about the change. You must be
        an administrator.

        Args:
            person_id: Person unique identifier
            password: New password
            password_2: Password confirmation

        ``POST /actions/persons/{person_id}/change-password``
        """
        return await self._t.request(
            "POST",
            "/actions/persons/{person_id}/change-password",
            path_params={"person_id": person_id},
            body={"password": password, "password_2": password_2},
            extra_body=extra_body,
            body_mode="json_props",
            response_type=ChangePasswordOfPersonResponse,
        )

